WITH base_bal AS ( SELECT CTACTB, SUM(CASE WHEN DATE_FORMAT(REFERENCIA, '%Y-%m') = DATE_FORMAT(DATE(:VAR_DATA_REF_DRE), '%Y-%m') THEN VLRLANC ELSE 0 END) AS soma_ate_atu, SUM(CASE WHEN DATE_FORMAT(REFERENCIA, '%Y-%m') = DATE_FORMAT(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR), '%Y-%m') THEN VLRLANC ELSE 0 END) AS soma_ate_ant FROM IMP_BASE_BALANCETE WHERE CODEMP = :VAR_EMPRESA_DRE GROUP BY CTACTB ) SELECT DET.ORDEM, DET.NOME_GRUPO, SUM(IFNULL(B.soma_ate_atu, 0) * DETCTACTB.SINAL) AS ANO_ATUAL, SUM(IFNULL(B.soma_ate_ant, 0) * DETCTACTB.SINAL) AS ANO_ANTERIOR FROM ESTR_DEMONSTRATIVOS EST INNER JOIN DET_DEMONSTRATIVO DET ON EST.ID = DET.ID_ESTR_DEMONSTRATIVO INNER JOIN DET_DEMONSTRATIVO_REFERENCIA DETREF ON DET.ID = DETREF.ID_DET_DEMONSTRATIVO LEFT JOIN DET_DEMONSTRATIVO_CTACTB DETCTACTB ON DETREF.ID = DETCTACTB.ID_DET_DEMONSTRATIVO_REFERENCIA LEFT JOIN base_bal B ON B.CTACTB = DETCTACTB.PADRAO_CTACTB WHERE EST.ID = 2 GROUP BY DET.ORDEM, DET.NOME_GRUPO ORDER BY DET.ORDEM
